def C_k_m(k, m):
    # C_k(m) = 7^k (2 - m + k) - k 7^(k-1)
    if k == 0:
        return 1 * (2 - m + 0) - 0 # Note: k*7^(k-1) term is 0 if k=0, but 7^(-1) is tricky. C_0(m) should be 2-m.
    return (7**k) * (2 - m + k) - k * (7**(k-1))

