def solve_diophantine():
    count = 0
    # Equation: 343 = 49*b3 + 21*b2 + 5*b1 + b0
    # Constraints: 0 <= bi <= 6

    for b3 in range(7):
        remaining_after_b3 = 343 - 49 * b3
        if remaining_after_b3 < 0:
            break

        for b2 in range(7):
            remaining_after_b2 = remaining_after_b3 - 21 * b2
            if remaining_after_b2 < 0:
                break

            for b1 in range(7):
                remaining_after_b1 = remaining_after_b2 - 5 * b1
                if remaining_after_b1 < 0:
                    break

                # b0 must be remaining_after_b1
                b0 = remaining_after_b1

                # Check constraints on b0
                if 0 <= b0 <= 6:
                    count += 1
                    # print(f"Solution found: b3={b3}, b2={b2}, b1={b1}, b0={b0}") # For debugging

    return count

